-- ISOLATED LOCAL TEST DATABASE ONLY. Never run this fixture on Supabase.
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";
DO $$BEGIN IF NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname='anon') THEN CREATE ROLE anon; END IF; IF NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname='authenticated') THEN CREATE ROLE authenticated; END IF; IF NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname='service_role') THEN CREATE ROLE service_role BYPASSRLS; END IF; END$$;
CREATE SCHEMA auth; CREATE SCHEMA storage;
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$SELECT NULLIF(current_setting('request.jwt.claim.sub',true),'')::uuid$$;
CREATE TABLE auth.users(id uuid PRIMARY KEY,email text,raw_user_meta_data jsonb DEFAULT '{}');
CREATE TABLE public.profiles(id uuid PRIMARY KEY REFERENCES auth.users,email text NOT NULL,first_name text,last_name text,phone text,state text,country text,account_type text,is_admin boolean DEFAULT false,is_verified boolean DEFAULT false,avatar_url text,bio text,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE TABLE public.site_settings(id int PRIMARY KEY DEFAULT 1,company_name text,email text,phone text,whatsapp text,address text,inspection_fee int,updated_at timestamptz DEFAULT now(),updated_by uuid);
CREATE TABLE public.properties(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid REFERENCES public.profiles,title text,slug text,status text DEFAULT 'available',verification_status text DEFAULT 'pending',featured boolean DEFAULT false,sample boolean DEFAULT false,images text[] DEFAULT '{}',coordinates jsonb,views int DEFAULT 0,saves int DEFAULT 0,enquiries_count int DEFAULT 0,description text,updated_at timestamptz DEFAULT now(),published_at timestamptz,date_added timestamptz DEFAULT now());
CREATE TABLE public.property_images(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),property_id uuid REFERENCES public.properties,url text,display_order int DEFAULT 0,is_primary boolean DEFAULT false);
CREATE TABLE public.property_documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),property_id uuid);
CREATE TABLE public.property_views(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),property_id uuid);
CREATE TABLE public.reviews(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid REFERENCES auth.users,email text,name text,rating int,title text,message text,location text,status text DEFAULT 'pending',is_verified_buyer boolean DEFAULT false,updated_at timestamptz DEFAULT now(),created_at timestamptz DEFAULT now());
CREATE TABLE public.agencies(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text,slug text,email text,phone text,description text,address text,state text,logo_url text,website text,is_verified boolean DEFAULT false,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE TABLE public.agents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid,agency_id uuid,name text,slug text,email text,phone text,whatsapp text,photo_url text,bio text,is_verified boolean DEFAULT false,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE TABLE public.developments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text,slug text,status text,site_inspection text,documentation jsonb,amenities jsonb,features jsonb,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE TABLE public.conversations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),property_id uuid,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE TABLE public.conversation_participants(conversation_id uuid REFERENCES public.conversations,user_id uuid REFERENCES public.profiles,created_at timestamptz DEFAULT now(),PRIMARY KEY(conversation_id,user_id));
CREATE TABLE public.messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),conversation_id uuid REFERENCES public.conversations,sender_id uuid REFERENCES public.profiles,recipient_id uuid REFERENCES public.profiles,content text,is_read boolean DEFAULT false,created_at timestamptz DEFAULT now(),attachment_url text);
CREATE TABLE public.notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid,type text,title text,message text,data jsonb,is_read boolean DEFAULT false,created_at timestamptz DEFAULT now());
CREATE TABLE public.viewing_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid,property_id uuid,preferred_date date,preferred_time text,status text DEFAULT 'requested',created_at timestamptz DEFAULT now());
CREATE TABLE public.contact_messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text,email text,phone text,subject text,message text,status text DEFAULT 'new',created_at timestamptz DEFAULT now());
CREATE TABLE public.enquiries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),buyer_id uuid,status text DEFAULT 'new');
CREATE TABLE public.sent_emails(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),sender_id uuid);
CREATE TABLE public.admin_activity(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),admin_id uuid);
CREATE TABLE public.audit_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid);
CREATE TABLE storage.buckets(id text PRIMARY KEY,name text,public boolean DEFAULT false,file_size_limit bigint,allowed_mime_types text[]);
CREATE TABLE storage.objects(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),bucket_id text REFERENCES storage.buckets,name text);
ALTER TABLE storage.objects ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.property_views ENABLE ROW LEVEL SECURITY;
GRANT USAGE ON SCHEMA public,auth,storage TO anon,authenticated,service_role;
GRANT ALL ON ALL TABLES IN SCHEMA public,storage TO anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION auth.uid() TO anon,authenticated,service_role;
