CREATE POLICY "Owners can view own properties" ON properties FOR SELECT TO authenticated USING(owner_id=auth.uid());
CREATE POLICY "Owners can update own properties" ON properties FOR UPDATE TO authenticated USING(owner_id=auth.uid()) WITH CHECK(owner_id=auth.uid());
CREATE POLICY "Owners and agents can submit properties" ON properties FOR INSERT TO authenticated WITH CHECK(owner_id=auth.uid());

